{
  "name": "通用数据流接口",
  "name_en": "Generic Stream Interface",
  "manufacturer": "",
  "description": "这不是可明确识别的单一物理仪器，而是一类通用通信流接口，用于在实验室自动化中通过串口、网络套接字或进程管道与仪器交换原始字节数据，完成数据读取、发送与连接关闭。",
  "description_en": "This is not a clearly identifiable single physical instrument, but a generic communication stream interface used in laboratory automation to exchange raw byte data with instruments over serial links, network sockets, or piped processes, including reading, writing, and closing the connection.",
  "actions": [
    {
      "action_name": "auto-read",
      "description": "从数据流中读取指定字节数的数据。",
      "description_en": "Read a specified number of bytes from the stream."
    },
    {
      "action_name": "auto-write",
      "description": "向数据流写入打包后的数据。",
      "description_en": "Write packed data to the stream."
    },
    {
      "action_name": "auto-close",
      "description": "干净地关闭数据流连接。",
      "description_en": "Close the stream connection cleanly."
    }
  ],
  "tag_hints": [
    "instrument communication",
    "serial communication",
    "socket communication",
    "byte stream I/O",
    "lab automation connectivity",
    "process pipe communication"
  ]
}

